INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492581-econ306', 'stk-user9840', 'ECON 306', 'info', '{"desc": "الكورس اسمه حاليا ECON 206\nEconomy of Saudi Arabia\n\nالكورس جدا ممتع ومفيد\nOpen course\nلايوجد كتاب للكورس لذلك كل دكتور يدرس بطريقته\n\nعند Matthias Pickl\n\nالكورس انا اسميه كورس الرؤية فهو مخصص لذلك والمتيريل يتحدث بشكل مستمر طبقا للاحداث الاقتصادية والتغييرات اللي تصير في المملكة حاليا .\n\nفي البداية يبدا\nبتقييم وتحليل للوضع الاقتصادي الحالي للمملكة في ضل الاعتماد التام على النفط\nبعدها يبدا بتحليل القطاعات التي تحتاج لتنمية وتأثيرها على الاقتصاد وفق الرؤية 2030\nوكذلك يتطرق لل Game Theory\nstrategic behavior for OPEC against U.S Shale oil threats\n\nيتطرق لل Tourism والمشاريع التي تخدم تطويره\nPetrochemical\nRetailing\nHealthcare\nMining\nManufacturing\nIPO OF ARAMCO\nFinancing\nConstruction\nوالقائمة تطول والموضوع اللي اراه جدا ممتع ومفيد هو موضوع طرح ارامكو للاكتتاب …\n\nالكورس يتمتع بمستوى طرح وحرية عالية في التعبير والتقييم عما يحدث من تغيرات اقتصادية اجتماعية في المملكة …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-306-economy-of-saudi-arabia/121031/3", "user": "user9840", "ts": 1526554707000, "tid": 121031, "pn": 3}}', 1526554707000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10407-econ306', 'stk-user10407', 'ECON 306', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 306 - 181\nالتحضير :مافي تحضير\nطريقة الشرح : يكتب على السبورة كل كلاس\nالكويزات : كويز كل كلاس مدته دقيقة ( الكويز عبارة عن سؤال واحد من شرح الكلاس الماضي )\nالمياجر: اسئلة مثل الكويزات\nالفاينلات : نفس وضع الميد و يجيب سؤالين من الميد كبي بيست في الفاينل\nالقريد النهائي: A\nالصوت: ضعيف نوعا ما\nإضافات : الدكتور متعاون جدا و متفهم\nهذا توزيع الدرجات\n\nA\\+ .............. 7A .............. 7B\\+ .............. 2B ............... 8C\\+ ............... 6C ............... 3D\\+ .............. 1الكويزات عليها 30% الميدتيرم 30% الفاينل 40%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504547-econ306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/16", "user": "user10407", "ts": 1546716078000, "tid": 98252, "pn": 16}}]}', 1546716078000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-econ306', 'stk-sadguts', 'ECON 306', 'doc', '{"docs": [{"id": "stk-dr-f98259", "n": "Dr. Abdullah Mohammed Al Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON306 - Term 211\nالتحضير : بالبداية\nطريقة الشرح : شرح الدكتور عبدالله رهيب ومفيد جدا ونوتاته اسطورية رح تتعلم كثير عن اقتصاد السعودية\nقروب اسايمنتس: الدكتور مايحط كويزات ولكن يحط اسايمنتات تسويها انت وقروبك صعبة وتاخذ وقت لكن تصحيحه جيد\nالميد والفاينل: متوسطة لكن فيه فقرات فيها تركات مالها داعي ولا تقيس الفهم\nإضافات : الدكتور اسطورة ومادته مفيدة خصوصا لطلاب الفايننس ومو صعب مره تطلع معه بقريد لكن مع الدكتور تكره اي طاري للدرجات والتوزيع. ماحبيت شغل القروبات والاسايمنتات الطويلة ولا انه كان يمر الترم كامل بدون مايوضح الاختبارات والدرجات >> شخصيا تعلمت كثير لكن اشوف التفاصيل الي تعلمتها من المادة ذي ماتفيدني كثير ك طالب MIS\nعموما كانت تجربة جميلة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533783-econ306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdullah-mohammed-al-mansour/98259/19", "user": "SadGuts", "ts": 1645340280000, "tid": 98259, "pn": 19}}]}', 1645340280000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousefli-econ306', 'stk-yousefli', 'ECON 306', 'doc', '{"docs": [{"id": "stk-dr-f179337", "n": "Dr. Matthias Pickl", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ306-191\n\nالتحضير : كل يوم اخر الكلاس عن طريق ورقة.\n\nطريقة الشرح : سلايدات و نقاشات. الكلاس ممتع جدا لدرجة اني حضرت اغلبهم ما احب اغيب لانه ممتع ما تمل\n\nالكويزات: مافي.\n\nالبرزتيشن: مجموعات وكريم في الدرجات + احضر ٥ واسئل سؤال واحد وحط لك نجمة يم اسمك عليها درجات ترى\n\nالسميوليشن: يخليك تجرب بعض الاشياء الواقعية واحيانا يصير تفاعل مثل يقسم الكلاس\nلبائعين ومشتريين ويوزع اوراق عشان هذا يشتري والخخ المهم تفاعل صار والفكرة ما تطلع\nفما راح تمل + احضر عليه خصم ترى لو تغيب انتكبوا العيال ف اخذ درجات لا تطيرهم\n\nالهوموورك الوحيد: بلومبيرق ساعة بالكثير وما يطالع كم خذت المهم سويته تاخذ ٥ درجات مثل الحلاوة\n\nميدترم: متوسط + شوف الترم اللي قبلك.\n\nالفاينلات :متوسط، من البرزتيشن طويل مرهه لكن يجيب main points + شوف الترم اللي قبلك حق الاسئلة العامة لان يرفع لك\nشيئين البرزتيشن حق المجموعات تقريبا كان ٥٠٠ سلايد شيء كذا بسبة الشباب تحمسو وكل واحد يحط اكثر وانتكبنا + بعض الاشياء اللي اهو مسويها\n\nتصحيحه: جدا ممتاز.\n\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\n\n- الدكتور طيب ومحترم\n- الدكتور متمكن في المادة وما بتحس فيها طول الترم بس تحتاج جهد بسيط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518391-econ306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/matthias-pickl/179337/7", "user": "yousefli", "ts": 1577472094000, "tid": 179337, "pn": 7}}]}', 1577472094000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
